                            <input type="checkbox" :id="'task-' + task.id" :checked="task.is_completed" @change="toggleStatus(task)" class="h-5 w-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer">
                            <label :for="'task-' + task.id" class="ml-3 block text-sm font-medium text-gray-900 cursor-pointer">
                                <span :class="{'line-through text-gray-500': task.is_completed}" x-text="task.title"></span>
                            </label>
                        </div>
                        <button @click="deleteTask(task.id)" class="text-gray-400 hover:text-red-600 focus:outline-none focus:ring-2 focus:ring-red-500 rounded-full p-1 transition-colors opacity-0 group-hover:opacity-100 focus:opacity-100" :aria-label="'Delete task: ' + task.title">
                            <i class="fas fa-trash-alt" aria-hidden="true"></i>
                        </button>
                    </li>
                </template>
                <template x-if="!isLoading && filteredTasks().length === 0">
                    <li class="p-6 text-center text-gray-500">
                        <span x-show="currentFilter === 'all'">No tasks yet. Add one above!</span>
                        <span x-show="currentFilter === 'active'">No active tasks. Great job!</span>
                        <span x-show="currentFilter === 'completed'">No completed tasks.</span>
                    </li>
                </template>
            </ul>
        </section>
    </div>
</div>

<script>
    function taskManager() {
        return {
            tasks: [],
            currentFilter: 'all',
            newTaskTitle: '',
            isLoading: true,
            error: null,

            init() {
                const token = localStorage.getItem('authToken');
                if (!token) {
                    window.location.href = '/login';
                    return;
                }
                this.fetchTasks();
            },

            async fetchTasks() {
                this.isLoading = true;
                this.error = null;
                try {
                    const token = localStorage.getItem('authToken');
                    const response = await fetch('/api/tasks/', {
                        headers: {
                            'Authorization': `Bearer ${token}`,
                            'Content-Type': 'application/json'
                        }
                    });

                    if (!response.ok) {
                        if (response.status === 401) {
                            this.logout();
                            return;
                        }
                        const errorData = await response.json().catch(() => ({ detail: 'Failed to fetch tasks.' }));
                        throw new Error(errorData.detail || 'An unknown error occurred.');
                    }
                    this.tasks = await response.json();
                } catch (err) {
                    this.error = err.message;
                } finally {
                    this.isLoading = false;
                }
            },

            filteredTasks() {
                if (this.currentFilter === 'active') {
                    return this.tasks.filter(task => !task.is_completed);
                }
                if (this.currentFilter === 'completed') {
                    return this.tasks.filter(task => task.is_completed);
                }
                return this.tasks;
            },

            async addTask() {
                if (!this.newTaskTitle.trim()) return;
                this.error = null;

                try {
                    const token = localStorage.getItem('authToken');
                    const response = await fetch('/api/tasks/', {
                        method: 'POST',
                        headers: {
                            'Authorization': `Bearer ${token}`,
                            'Content-Type': 'application/json'
                        },
                        body: JSON.stringify({ title: this.newTaskTitle.trim() })
                    });

                    if (!response.ok) {
                        const errorData = await response.json().catch(() => ({ detail: 'Failed to add task.' }));
                        throw new Error(errorData.detail || 'An unknown error occurred.');
                    }
                    const newTask = await response.json();
                    this.tasks.push(newTask); // Optimistic update
                    this.newTaskTitle = '';
                } catch (err) {
                    this.error = err.message;
                }
            },

            async updateTask(id, data) {
                this.error = null;
                const originalTasks = JSON.parse(JSON.stringify(this.tasks));

                // Optimistic UI update
                const taskIndex = this.tasks.findIndex(t => t.id === id);
                if (taskIndex !== -1) {
                    this.tasks[taskIndex] = { ...this.tasks[taskIndex], ...data };
                }

                try {
                    const token = localStorage.getItem('authToken');
                    const response = await fetch(`/api/tasks/${id}`, {
                        method: 'PUT',
                        headers: {
                            'Authorization': `Bearer ${token}`,
                            'Content-Type': 'application/json'
                        },
                        body: JSON.stringify(data)
                    });

                    if (!response.ok) {
                        throw new Error('Failed to update task.');
                    }
                } catch (err) {
                    this.error = err.message;
                    this.tasks = originalTasks; // Revert on failure
                }
            },

            async deleteTask(id) {
                if (!confirm('Are you sure you want to delete this task?')) {
                    return;
                }

                this.error = null;
                const originalTasks = [...this.tasks];
                this.tasks = this.tasks.filter(task => task.id !== id); // Optimistic UI update

                try {
                    const token = localStorage.getItem('authToken');
                    const response = await fetch(`/api/tasks/${id}`, {
                        method: 'DELETE',
                        headers: {
                            'Authorization': `Bearer ${token}`
                        }
                    });

                    if (!response.ok) {
                        throw new Error('Failed to delete task.');
                    }
                } catch (err) {
                    this.error = err.message;
                    this.tasks = originalTasks; // Revert on failure
                }
            },

            toggleStatus(task) {
                this.updateTask(task.id, { is_completed: !task.is_completed });
            },

            logout() {
                localStorage.removeItem('authToken');
                window.location.href = '/login';
            }
        }
    }
</script>
{% endblock %}
